'use strict';
const sky=EldoriaSkyModel;sky.ensure(state);
const skyCSS=document.createElement('link');skyCSS.rel='stylesheet';skyCSS.href='city-sky.css?v=1';document.head.append(skyCSS);
const skyButton=document.createElement('button');skyButton.id='skyLighting';skyButton.onclick=skySettings;atmosphereBar.append(skyButton);
const skyEventsButton=document.createElement('button');skyEventsButton.id='skyEvents';skyEventsButton.textContent='Holidays & events';skyEventsButton.onclick=skyEvents;atmosphereBar.append(skyEventsButton);
let skyLast='';
function skySync(){const c=atmosphere.conditions(state),phase=sky.light(state,c),el=$('cityScene');el.dataset.lightPhase=phase;el.dataset.lightInterior=String(citySheltered());const preview=sky.ensure(state).view!=='auto';skyButton.textContent=(phase==='night'?'☾ ':phase==='dusk'?'◒ ':'☀ ')+atCap(phase)+(preview?' preview':' · Real clock');skyButton.setAttribute('aria-label','Day & night: '+atCap(phase)+(preview?' preview':' following real clock'));$('cityWeather').textContent=atCap(phase)+(preview?' preview':'')+' · '+weatherNames[c.weather];const current=sky.today(c);el.dataset.holiday=String(current.length>0);skyEventsButton.textContent=current.length?'✦ '+current[0].title:'Holidays & events';const key=(phase==='night'?'night':'day')+':'+scene+':'+cityInside+':'+cityTreehousePorch;if(skyLast&&skyLast!==key)cityPaintScene();skyLast=key;return phase}
function skySettings(){modal('Day & night across Eldoria','<p>The sun follows the real clock and the selected season. Explore moonlit streets, golden cottage windows and the illuminated treehouse whenever you like.</p><p>A lighting preview changes the scenery only. Your real date, neighbors’ schedules and the Midnight Promise keep their actual time.</p><div id="skyChoices" class="sky-choices"></div><p id="skyStatus" role="status"></p>');for(const [mode,label]of [['auto','Follow the real clock'],['day','Preview daylight'],['night','Preview nighttime']]){const b=action(label,()=>{sky.ensure(state).view=mode;skySync();persist();skySettings()});b.dataset.skyView=mode;b.setAttribute('aria-pressed',String(state.citySky.view===mode));$('skyChoices').append(b)}$('skyStatus').textContent='Current view: '+atCap(sky.light(state,atmosphere.conditions(state)))+'.';action('Explore with this lighting',()=>{$('modal').close();cityDraw()});action('Weather & all four seasons',atSettings);action('Holiday & seasonal events',skyEvents)}
function skyEventDetail(id,year){const c=atmosphere.conditions(state),e=sky.events(year).find(e=>e.id===id);if(!e)return;modal(e.title,'<p>'+lifeEsc(e.key)+' · Eldoria County</p><p>'+lifeEsc(e.text)+'</p><p>'+(c.key===e.key?'Happening today! Celebrate at Embermere Campground.': 'Returns on this real calendar date in your selected timezone. Seasonal gatherings and camping are available in the meantime.')+'</p>');if(c.key===e.key){action(state.citySky.claimed[e.claim]?'Revisit this holiday celebration':'Join the holiday activity',()=>countyVisit('countyCamp',()=>lifePuzzle('county_'+e.puzzle,e.title,answer=>sky.celebrate(state,id,atmosphere.conditions(state),answer))))}action('Visit the bonfire campground',countyVisitCamp);action('Back to holidays & events',skyEvents)}
function skyEvents(){const c=atmosphere.conditions(state);modal('Eldoria’s holidays & seasonal gatherings','<p>Holiday dates follow the real calendar in '+lifeEsc(c.timeZone)+'. Join on the day for a playable celebration, 25 mooncoins and a keepsake for your legacy room.</p><div id="skyEventList"></div>');const area=$('skyEventList');for(const e of [...sky.events(c.year),...sky.events(c.year+1)].filter(e=>e.key>=c.key).slice(0,8)){const b=document.createElement('button');b.className='sky-event';b.innerHTML='<strong>'+lifeEsc(e.title)+'</strong><span>'+e.key+(e.key===c.key?' · TODAY':'')+'</span>';b.onclick=()=>skyEventDetail(e.id,e.year);area.append(b)}for(const [season,e]of Object.entries(county.seasons)){const p=document.createElement('p');p.textContent=atCap(season)+' · '+e.title+(season===c.season?' · Happening this season':'');area.append(p)}const p=document.createElement('p');p.textContent='Every Saturday: Embermere Bonfire Gathering. Camping, cooking, singing, stories and stargazing are available every day.';area.append(p);action('Join this season’s gathering',countySeason);action('Visit the bonfire campground',countyVisitCamp);action('Open the dated calendar',()=>atCalendar(0));action('Weather & seasons',atSettings)}
const skyCalendarCellsBefore=atCalendarCells;atCalendarCells=function(){skyCalendarCellsBefore();if(!$('atCalendarGrid'))return;const c=atmosphere.conditions(state),grid=atmosphere.monthGrid(c.year,c.month-1+atMonthOffset),events=sky.events(grid.year);const cells=[...$('atCalendarGrid').children].slice(7);cells.forEach((cell,i)=>{const day=grid.cells[i];if(!day)return;const holiday=events.find(e=>e.month===grid.month+1&&e.day===day),sat=new Date(Date.UTC(grid.year,grid.month,day)).getUTCDay()===6;if(!holiday&&!sat)return;const button=document.createElement('button');button.className=cell.className+' sky-calendar-event';button.textContent=day+(holiday?' ✦':' ♧');button.title=holiday?holiday.title:'Saturday bonfire gathering';button.setAttribute('aria-label',day+' '+button.title);if(cell.hasAttribute('aria-current'))button.setAttribute('aria-current','date');button.onclick=holiday?()=>skyEventDetail(holiday.id,grid.year):countyVisitCamp;cell.replaceWith(button)})};
const skyCalendarBefore=atCalendar;atCalendar=function(offset=0){skyCalendarBefore(offset);const p=document.createElement('p');p.textContent='✦ Holiday celebration · ♧ Saturday bonfire. Select a marked date for details.';$('atCalendarGrid').after(p);action('All holidays & seasonal events',skyEvents)};$('atCalendar').onclick=()=>atCalendar(0);window.ELDORIA_ATMOSPHERE.openCalendar=atCalendar;
const skyAtSyncBefore=atSync;atSync=function(){const c=skyAtSyncBefore();skySync();return c};
const skyDrawBefore=cityDraw;cityDraw=function(){skyDrawBefore();skySync()};comfortDraw=cityDraw;
window.ELDORIA_SKY={version:1,openLighting:skySettings,openEvents:skyEvents,get phase(){return sky.light(state,atmosphere.conditions(state))}};skySync();cityDraw();persist();setInterval(skySync,1000);
